$ErrorActionPreference = 'Stop'

$app = Join-Path (Get-Location) 'src/app'
$providerFolder = Join-Path $app 'provider'
$dataFolder = Join-Path (Get-Location) 'src/data'

New-Item -ItemType Directory -Force $app, $providerFolder, $dataFolder | Out-Null

$files = @{}

$files[(Join-Path $dataFolder 'providers.ts')] = @'
export type Provider = {
  id: string;
  name: string;
  service: string;
  categoryId: string;
  subcategoryId: string;
  locationId: string;
  locationName: string;
  rating: number;
  reviews: number;
  distance: string;
  verified: boolean;
  available: boolean;
  phone: string;
  whatsapp: string;
  description: string;
  coverage: string[];
};

export const PROVIDERS: Provider[] = [
  { id: 'servicios-ranco', name: 'Servicios del Ranco', service: 'Electricidad y reparaciones', categoryId: 'hogar', subcategoryId: 'electricidad', locationId: 'lago-ranco', locationName: 'Lago Ranco', rating: 4.9, reviews: 38, distance: '1,8 km', verified: true, available: true, phone: '+56987654321', whatsapp: '56987654321', description: 'Instalaciones, reparaciones y mantenciones domiciliarias con atención en sectores urbanos y rurales.', coverage: ['Lago Ranco', 'Riñinahue', 'Ilihue'] },
  { id: 'soluciones-rios', name: 'Soluciones Los Ríos', service: 'Energía solar y electricidad', categoryId: 'energia', subcategoryId: 'solar', locationId: 'futrono', locationName: 'Futrono', rating: 4.8, reviews: 24, distance: '3,2 km', verified: true, available: true, phone: '+56976543210', whatsapp: '56976543210', description: 'Diseño e instalación de sistemas solares, baterías, inversores y respaldo energético.', coverage: ['Futrono', 'Llifen', 'Lago Ranco'] },
  { id: 'maestro-patricio', name: 'Maestro Patricio', service: 'Gasfitería y hogar', categoryId: 'hogar', subcategoryId: 'gasfiteria', locationId: 'futrono', locationName: 'Futrono', rating: 4.7, reviews: 19, distance: '5,1 km', verified: false, available: true, phone: '+56965432109', whatsapp: '56965432109', description: 'Reparación de filtraciones, grifería, calefón, cañerías y emergencias domiciliarias.', coverage: ['Futrono', 'Llifen'] },
  { id: 'integrales-futrono', name: 'Servicios Integrales Futrono', service: 'Mantención y construcción', categoryId: 'hogar', subcategoryId: 'carpinteria', locationId: 'futrono', locationName: 'Futrono', rating: 4.6, reviews: 31, distance: '7,4 km', verified: true, available: false, phone: '+56954321098', whatsapp: '56954321098', description: 'Equipo local para reparaciones, ampliaciones, pintura, carpintería y mantención general.', coverage: ['Futrono', 'Llifen', 'Nontuelá'] },
];

export const getProvider = (id?: string) => PROVIDERS.find((item) => item.id === id) ?? PROVIDERS[0];
'@

$files[(Join-Path $app 'providers.tsx')] = @'
import { Ionicons } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { FlatList, Pressable, SafeAreaView, StyleSheet, Text, TextInput, View } from 'react-native';
import { PROVIDERS } from '../data/providers';

export default function ProvidersScreen() {
  const params = useLocalSearchParams<{ serviceName?: string; locationName?: string; subcategoryId?: string }>();
  const serviceName = String(params.serviceName || 'Prestadores');
  const locationName = String(params.locationName || 'Lago Ranco');
  const [search, setSearch] = useState('');
  const data = useMemo(() => PROVIDERS.filter((item) => item.name.toLowerCase().includes(search.toLowerCase())), [search]);
  return <SafeAreaView style={s.safe}><FlatList data={data} keyExtractor={(i) => i.id} contentContainerStyle={s.content} ListHeaderComponent={<><View style={s.bar}><Pressable onPress={() => router.back()} style={s.iconBtn}><Ionicons name="arrow-back" size={23} color="#17382A" /></Pressable><View style={s.heading}><Text style={s.barTitle}>{serviceName}</Text><Text style={s.muted}>{locationName}</Text></View><Pressable style={s.iconBtn}><Ionicons name="options-outline" size={21} color="#276749" /></Pressable></View><View style={s.hero}><Text style={s.eyebrow}>PRESTADORES DISPONIBLES</Text><Text style={s.heroTitle}>{serviceName} en {locationName}</Text><Text style={s.heroText}>Compara experiencia, valoración y disponibilidad.</Text></View><View style={s.search}><Ionicons name="search-outline" size={20} color="#718077" /><TextInput value={search} onChangeText={setSearch} placeholder="Buscar prestador" style={s.input} /></View><Text style={s.section}>Resultados</Text></>} renderItem={({ item }) => <Pressable onPress={() => router.push({ pathname: '/provider/[providerId]', params: { providerId: item.id } })} style={s.card}><View style={s.avatar}><Ionicons name="person" size={24} color="#276749" /></View><View style={s.info}><View style={s.nameRow}><Text style={s.name}>{item.name}</Text>{item.verified && <Ionicons name="checkmark-circle" size={17} color="#3B8460" />}</View><Text style={s.muted}>{item.service}</Text><View style={s.meta}><Ionicons name="star" size={14} color="#D78A2F" /><Text style={s.rating}>{item.rating}</Text><Text style={s.muted}>({item.reviews}) · {item.distance}</Text></View><Text style={[s.status, !item.available && s.busy]}>{item.available ? 'Disponible' : 'Consultar disponibilidad'}</Text></View><Ionicons name="chevron-forward" size={20} color="#9AA69E" /></Pressable>} /></SafeAreaView>;
}

