import { Alert, Pressable, SafeAreaView, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
export default function RequestService(){const p=useLocalSearchParams<{providerName?:string;serviceName?:string}>();const [address,setAddress]=useState('');const [detail,setDetail]=useState('');const send=()=>{if(!address.trim()||!detail.trim())return Alert.alert('Faltan datos','Ingresa el sector y describe lo que necesitas.');Alert.alert('Solicitud enviada','El prestador podrá revisar y responder tu solicitud.',[{text:'Aceptar',onPress:()=>router.replace('/contacts')}]);};return <SafeAreaView style={s.safe}><ScrollView contentContainerStyle={s.content}><Header title="Solicitar servicio"/><View style={s.hero}><Text style={s.eyebrow}>SOLICITUD PARA</Text><Text style={s.title}>{String(p.providerName||'Prestador')}</Text><Text style={s.light}>{String(p.serviceName||'Servicio local')}</Text></View><Label text="Sector o dirección"/><TextInput value={address} onChangeText={setAddress} placeholder="Ej: Futrono, sector urbano" style={s.input}/><Label text="¿Qué necesitas resolver?"/><TextInput value={detail} onChangeText={setDetail} placeholder="Describe el trabajo con el mayor detalle posible" multiline style={[s.input,s.area]}/><Label text="Fecha preferida"/><Pressable style={s.selector}><Ionicons name="calendar-outline" size={20} color="#276749"/><Text style={s.selectorText}>Lo antes posible</Text><Ionicons name="chevron-down" size={18} color="#87938B"/></Pressable><Pressable style={s.attach}><Ionicons name="camera-outline" size={21} color="#276749"/><Text style={s.attachText}>Agregar fotografías</Text></Pressable><Pressable onPress={send} style={s.send}><Text style={s.sendText}>Enviar solicitud</Text><Ionicons name="send" size={18} color="#FFF"/></Pressable></ScrollView></SafeAreaView>};
function Header({title}:{title:string}){return <View style={s.bar}><Pressable onPress={()=>router.back()} style={s.back}><Ionicons name="arrow-back" size={23} color="#17382A"/></Pressable><Text style={s.barTitle}>{title}</Text><View style={{width:43}}/></View>}function Label({text}:{text:string}){return <Text style={s.label}>{text}</Text>}const s=StyleSheet.create({safe:{flex:1,backgroundColor:'#F5F7F2'},content:{width:'100%',maxWidth:680,alignSelf:'center',padding:16,paddingBottom:40},bar:{height:64,flexDirection:'row',alignItems:'center',justifyContent:'space-between'},back:{width:43,height:43,borderRadius:14,alignItems:'center',justifyContent:'center',backgroundColor:'#FFF',borderWidth:1,borderColor:'#E0E6E1'},barTitle:{fontSize:16,fontWeight:'800',color:'#17382A'},hero:{padding:21,borderRadius:22,backgroundColor:'#193E2E'},eyebrow:{fontSize:10,fontWeight:'800',letterSpacing:1.1,color:'#BFD3C4'},title:{fontSize:23,fontWeight:'800',color:'#FFF',marginTop:7},light:{fontSize:12,color:'#C7D5CB',marginTop:4},label:{fontSize:13,fontWeight:'800',color:'#243D30',marginTop:18,marginBottom:7},input:{minHeight:54,paddingHorizontal:15,borderRadius:16,backgroundColor:'#FFF',borderWidth:1,borderColor:'#DDE5DF',fontSize:14,color:'#243D30'},area:{height:130,paddingTop:14,textAlignVertical:'top'},selector:{height:55,paddingHorizontal:15,borderRadius:16,flexDirection:'row',alignItems:'center',gap:9,backgroundColor:'#FFF',borderWidth:1,borderColor:'#DDE5DF'},selectorText:{flex:1,fontSize:13,color:'#3D5145'},attach:{height:54,marginTop:14,borderRadius:16,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:8,backgroundColor:'#E7F0E9'},attachText:{fontSize:13,fontWeight:'800',color:'#276749'},send:{height:58,marginTop:20,borderRadius:18,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:9,backgroundColor:'#D17B3F'},sendText:{fontSize:16,fontWeight:'800',color:'#FFF'}});
