export default function Favorites(){const [items,setItems]=useState(PROVIDERS.slice(0,3));return <SafeAreaView style={s.safe}><FlatList data={items} keyExtractor={i=>i.id} contentContainerStyle={s.content} ListHeaderComponent={<><Header/><Text style={s.title}>Tus favoritos</Text><Text style={s.sub}>Prestadores que guardaste para encontrarlos rápidamente.</Text></>} renderItem={({item})=><Pressable onPress={()=>router.push({pathname:'/provider/[providerId]',params:{providerId:item.id}})} style={s.card}><View style={s.avatar}><Ionicons name="person" size={23} color="#276749"/></View><View style={s.info}><Text style={s.name}>{item.name}</Text><Text style={s.muted}>{item.service}</Text><Text style={s.rating}>★ {item.rating} · {item.locationName}</Text></View><Pressable onPress={()=>setItems(v=>v.filter(x=>x.id!==item.id))}><Ionicons name="heart" size={22} color="#D17B3F"/></Pressable></Pressable>} ListEmptyComponent={<View style={s.empty}><Ionicons name="heart-outline" size={45} color="#9AA69E"/><Text style={s.emptyTitle}>Todavía no tienes favoritos</Text></View>}/></SafeAreaView>};function Header(){return <View style={s.bar}><Pressable onPress={()=>router.back()} style={s.back}><Ionicons name="arrow-back" size={23} color="#17382A"/></Pressable><Text style={s.barTitle}>Favoritos</Text><View style={{width:43}}/></View>}const s=StyleSheet.create({safe:{flex:1,backgroundColor:'#F5F7F2'},content:{width:'100%',maxWidth:680,alignSelf:'center',padding:16},bar:{height:64,flexDirection:'row',alignItems:'center',justifyContent:'space-between'},back:{width:43,height:43,borderRadius:14,alignItems:'center',justifyContent:'center',backgroundColor:'#FFF'},barTitle:{fontWeight:'800',color:'#17382A'},title:{fontSize:27,fontWeight:'800',color:'#17382A',marginTop:10},sub:{fontSize:13,lineHeight:19,color:'#718077',marginTop:6,marginBottom:20},card:{minHeight:92,padding:14,marginBottom:10,borderRadius:19,flexDirection:'row',alignItems:'center',backgroundColor:'#FFF',borderWidth:1,borderColo