ignItems:'center',justifyContent:'center',backgroundColor:'#E4EFE7'},name:{fontSize:20,fontWeight:'800',color:'#FFF',marginTop:12},email:{fontSize:12,color:'#C7D5CB',marginTop:4},list:{marginTop:13,borderRadius:20,overflow:'hidden',backgroundColor:'#FFF',borderWidth:1,borderColor:'#E0E6E1'},option:{height:62,paddingHorizontal:14,flexDirection:'row',alignItems:'center',borderBottomWidth:1,borderBottomColor:'#EDF0ED'},optionIcon:{width:37,height:37,borderRadius:12,alignItems:'center',justifyContent:'center',backgroundColor:'#EAF3EC'},optionText:{flex:1,fontSize:13,fontWeight:'700',color:'#31483A',marginLeft:10},value:{fontSize:10,color:'#718077',marginRight:6},provider:{minHeight:85,padding:16,marginTop:13,borderRadius:20,flexDirection:'row',alignItems:'center',gap:11,backgroundColor:'#D17B3F'},providerTitle:{fontSize:14,fontWeight:'800',color:'#FFF'},providerText:{fontSize:11,color:'#F8E5D6',marginTop:3},logout:{height:54,marginTop:13,borderRadius:16,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:8,backgroundColor:'#F8E8E5'},logoutText:{fontSize:13,fontWeight:'800',color:'#A9473D'}});
