import { Ionicons } from '@expo/vector-icons';import { router } from 'expo-router';import { useState } from 'react';import { Alert,Pressable,SafeAreaView,ScrollView,StyleSheet,Text,TextInput,View } from 'react-native';
const CATS=['Hogar y reparaciones','Calefacción','Jardín y parcela','Energía y conectividad'];
export default function ProviderRegister(){const [name,setName]=useState('');const [phone,setPhone]=useState('');const [category,setCategory]=useState(CATS[0]);const [bio,setBio]=useState('');const save=()=>{if(!name||!phone)return Alert.alert('Faltan datos','Completa el nombre y teléfono.');Alert.alert('Perfil enviado','Revisaremos los datos antes de publicar el perfil.',[{text:'Aceptar',onPress:()=>router.back()}])};return <SafeAreaView style={s.safe}><ScrollView contentContainerStyle={s.content}><Header/><View style={s.hero}><Text style={s.eyebrow}>ÚNETE A RANCOCONECTA</Text><Text style={s.title}>Publica tus servicios</Text><Text style={s.light}>Conecta con personas que necesitan ayuda en tu localidad.</Text></View><Label t="Nombre o negocio"/><TextInput value={name} onChangeText={setName} placeholder="Ej: Electricidad Juan Pérez" style={s.input}/><Label t="Teléfono / WhatsApp"/><TextInput value={phone} onChangeText={setPhone} keyboardType="phone-pad" placeholder="+56 9..." style={s.input}/><Label t="Categoría principal"/><View style={s.chips}>{CATS.map(c=><Pressable key={c} onPress={()=>setCategory(c)} style={[s.chip,category===c&&s.chipActive]}><Text style={[s.chipText,category===c&&s.chipTextActive]}>{c}</Text></Pressable>)}</View><Label t="Descripción del servicio"/><TextInput value={bio} onChangeText={setBio} multiline placeholder="Experiencia, trabajos que realizas y cobertura" style={[s.input,s.area]}/><Label t="Localidades de cobertura"/><View style={s.selector}><Ionicons name="location-outline" size={19} color="#276749"/><Text style={s.selectorText}>Lago Ranco y Futrono</Text><Ionicons name="chevron-forward" size={18} color="#9AA69E"/></View><Pressable onPress={save} style={s.save}><Text style={s.saveText}>Enviar para revisión</Text><Ionicons name="arrow-forward" size={19} color="#FFF"/></Pressable></ScrollView></SafeAreaView>};function Header(){return <View style={s.bar}><Pressable onPress={()=>router.back()} style={s.back}><Ionicons name="arrow-back" size={23} color="#17382A"/></Pressable><Text style={s.barTitle}>Soy proveedor</Text><View style={{width:43}}/></View>}function Label({t}:{t:string}){return <Text style={s.label}>{t}</Text>}const s=StyleSheet.create({safe:{flex:1,backgroundColor:'#F5F7F2'},content:{width:'100%',maxWidth:680,alignSelf:'center',padding:16,paddingBottom:40},bar:{height:64,flexDirection:'row',alignItems:'center',justifyContent:'space-between'},back:{width:43,height:43,borderRadius:14,alignItems:'center',justifyContent:'center',backgroundColor:'#FFF'},barTitle:{fontWeight:'800',color:'#17382A'},hero:{padding:22,borderRadius:23,backgroundColor:'#193E2E'},eyebrow:{fontSize:10,fontWeight:'800',letterSpacing:1.1,color:'#BFD3C4'},title:{fontSize:27,fontWeight:'800',color:'#FFF',marginTop:8},light:{fontSize:13,lineHeight:19,color:'#C7D5CB',marginTop:7},label:{fontSize:13,fontWeight:'800',color:'#243D30',marginTop:17,marginBottom:7},input:{minHeight:54,paddingHorizontal:15,borderRadius:16,backgroundColor:'#FFF',borderWidth:1,borderColor:'#DDE5DF',fontSize:14},area:{height:120,paddingTop:14,textAlignVertical:'top'},chips:{flexDirection:'row',flexWrap:'wrap',gap:8},chip:{paddingHorizontal:11,paddingVertical:9,borderRadius:12,backgroundColor:'#FFF',borderWidth:1,borderColor:'#DDE5DF'},chipActive:{backgroundColor:'#276749',borderColor:'#276749'},chipText:{fontSize:11,fontWeight:'700',color:'#56675D'},chipTextActive:{color:'#FFF'},selector:{height:55,paddingHorizontal:15,borderRadius:16,flexDirection:'row',alignItems:'center',gap:8,backgroundColor:'#FFF',borderWidth:1,borderColor:'#DDE5DF'},selectorText:{flex:1,fontSize:13,color:'#3D5145'},save:{height:58,marginTop:21,borderRadius:18,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:9,backgroundColor:'#D17B3F'},saveText:{fontSize:15,fontWeight:'800',color:'#FFF'}});
